import{_ as d,o as e,c as r,ag as a}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Qoder 中国版体验","description":"AI Agent 零基础教程","frontmatter":{"title":"Qoder 中国版体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-qoder.md","filePath":"guide/05-qoder.md","lastUpdated":null}'),i={name:"guide/05-qoder.md"};function l(o,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="qoder-中国版体验" tabindex="-1">Qoder 中国版体验 <a class="header-anchor" href="#qoder-中国版体验" aria-label="Permalink to &quot;Qoder 中国版体验&quot;">​</a></h1><blockquote><p>状态：正文完成；共同基准任务已实测（2026-08-12）</p><p>本机版本：应用 1.23.0（底层壳字段 1.106.3；主窗口标题 Quest Window）</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p>本轮实测<strong>最快最省</strong>的产品：2 分钟完成 6/6 交付、6.32 Credits / ¥0.25，任务卡直接展示人民币费用，审查视图支持暂存/丢弃/提交。但存在<strong>关键安全边界问题</strong>：在无权限弹窗的情况下读取了 input 之外的工作区文件，且自检未发现——「0 弹窗」不等于「合规」，效率与边界必须分开评价。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（统一基准实测）；界面截图核验 2026-08-13</li><li>正式产品名称与测试入口：Qoder 中国版（<code>QoderCN</code>；同目录另有国际版 <code>Qoder</code> 与 <code>QoderWork CN</code>，三者不能共享价格/福利/截图结论）</li><li>地区版本：中国版（必须使用中国站价格，不使用国际站 $20/$60/$200）</li><li>具体产品线：IDE / Quest Mode（以 Quest 为任务单位，形态接近 Agent 项目控制台）</li><li>账号区域与计费币种：中国区账号；人民币计价（Credits）</li><li>当前账号状态：正常（测试时）</li><li>官方服务是否覆盖当前地区：中国区官方运营</li><li>注册、登录与支付前提：中国站账号 + 支付方式</li><li>账号受限后的申诉与恢复入口：官方支持渠道（未触发）</li><li>桌面客户端版本：应用 1.23.0；底层壳字段 1.106.3</li><li>操作系统：Windows（本机安装于 <code>E:\\Program\\Qoder\\QoderCN</code>）</li><li>官方下载来源：Qoder 中国站</li><li>入门分组：代码优先型 Agent（国内）</li><li>主要任务方向：代码 / 综合任务（Quest）</li><li>开放与后台运行方式：云端（Credits 计费）</li><li>自主程度：中—高</li><li>建议基础：一般数字工具经验（代码用户友好）</li><li>使用方案：体验版 / 专业版 / 高级版 / 旗舰版（个人）</li><li>官方订阅名称、价格与周期：体验版 ¥0（2 周、300 Credits）；专业版 ¥59/月、2,000 Credits；高级版 ¥169/月、6,000 Credits；旗舰版 ¥559/月、20,000 Credits（当前按钮显示「敬请期待」）</li><li>套餐内用量单位：Credits；Plan Credits 按购买日形成周期、到期不结转；Add-on Credits 有独立有效期</li><li>用量重置时间与结转规则：按购买日周期；到期未使用不结转</li><li>官方 API 是否另行计费：个人专业版支持 API Key 接入阿里云百炼、智谱、Kimi、MiniMax；自定义模型由供应商结算，不消耗 Qoder CN Credits</li><li>是否支持 BYOK：支持（中国区各家 API Key）</li><li>免费额度及核验来源：体验版 2 周 / 300 Credits；个人资源包 ¥40/1,000 Credits（购买日起 1 个月有效）</li><li>新用户或学生福利：官方文档中「新用户 2,000 Credits、学生/教师 4,000 Credits、邀请奖励」活动<strong>明确属于 QoderWork CN 桌面端个人版</strong>，页面标题标注 7 月 30 日截止——不能作为 2026-08-11 的 Qoder CN IDE 当前福利</li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：中国站下载桌面客户端，安装顺利；</li><li>是否必须注册、登录或绑定其他服务：需要中国站账号；</li><li>首次权限提示：本轮无权限弹窗（注意：无弹窗不等于严格限制读取范围，见问题章节）；</li><li>主界面导航：左侧按工作区组织 Quests 与 Chats，提供定时任务、Better Harness、知识中心、插件市场、账号与额度入口；中间任务对话；产物提供概要、终端、文件、审查和浏览器快捷入口；</li><li>新手从启动到完成第一个任务：打开 QoderCN 确认主窗口为 Quest → 新建/进入 Quest → 选择工作空间 → 粘贴提示词 → 发送；</li><li>是否有只能通过 CLI/TUI 才能完成的重要能力：未发现。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>体验版 ¥0：2 周 / 300 Credits；资源包 ¥40/1,000 Credits（1 个月）</td><td>Qoder CN Pricing / Credits</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>专业版 ¥59/月（2,000 C）；高级版 ¥169/月（6,000 C）；旗舰版 ¥559/月（20,000 C，敬请期待）</td><td>Qoder CN Pricing</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>Credits；Plan 按购买日周期、不结转；Add-on 独立有效期</td><td>Qoder CN Credits</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>QoderWork CN 活动已截止（7 月 30 日），不适用于 Qoder CN</td><td>官方活动规则</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>专业版支持阿里云百炼/智谱/Kimi/MiniMax API Key</td><td>Qoder CN 自定义模型</td><td>2026-08-11</td></tr></tbody></table><p><strong>实测补充</strong>：本轮 Auto 配置（底层模型未显示），任务卡显示 2 分钟、6.32 Credits、¥0.25——成本展示最直观。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><ul><li>能处理哪些材料：文档、代码、项目文件；统一基准任务中一次生成 6 份 Markdown；</li><li>能调用哪些工具：文件系统、任务对话、交付报告、审查（暂存/丢弃/提交）（本轮用到）；定时任务、Better Harness、知识中心、插件市场入口可见；</li><li>代表性功能：最终交付报告表（文件名+路径+大小）、预览/代码双视图、审查视图（全部暂存/全部丢弃/提交）；</li><li>哪些能力实际验证过：共同基准任务完整链路；哪些只来自官方说明：Better Harness、知识中心等进阶能力。</li></ul><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：官方中国版桌面应用（云端处理）；</li><li>用户如何观察和控制执行过程：中间任务对话与交付报告，右侧文件树；产物提供概要/终端/文件/审查/浏览器入口。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>Quest 概念需要一次理解；熟悉代码的用户门槛低</td><td>—</td></tr><tr><td>账号与地区可用性</td><td>中国区正常；注意与 Qoder 国际版、QoderWork CN 区分</td><td>—</td></tr><tr><td>图形界面清晰度</td><td>Quest 控制台风格，交付报告表清晰</td><td>—</td></tr><tr><td>任务状态反馈</td><td>操作统计（已处理 25 个操作）+ 最终交付报告</td><td>—</td></tr><tr><td>权限提示与确认</td><td>本轮 0 弹窗；但读取越界发生在无弹窗情况下</td><td>过程控制 ≠ 范围控制</td></tr><tr><td>上下文处理</td><td><strong>越权读取</strong>：使用了 input 之外的工作区运行文件</td><td>需以产物与运行记录核对</td></tr><tr><td>过程可控性</td><td>审查视图可批量暂存/丢弃/提交</td><td>—</td></tr><tr><td>结果定位与验证</td><td>交付报告表（文件/路径/大小）+ 预览/代码切换</td><td>自检不可全信（见问题）</td></tr><tr><td>生态与扩展</td><td>定时任务、Harness、知识中心、插件市场入口</td><td>未逐一实测</td></tr></tbody></table><p>界面细节见 「界面讲解文档」(docs/11-interface-guides/03-qoder-cn.md)（三张截图：整体界面/交付报告、概览预览、审查视图）。</p><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务-2026-08-12" tabindex="-1">7.1 共同基准任务（2026-08-12） <a class="header-anchor" href="#_7-1-共同基准任务-2026-08-12" aria-label="Permalink to &quot;7.1 共同基准任务（2026-08-12）&quot;">​</a></h3><h4 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h4><p>使用冻结的教程材料包（<code>input/</code> 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检。</p><h4 id="完整输入" tabindex="-1">完整输入 <a class="header-anchor" href="#完整输入" aria-label="Permalink to &quot;完整输入&quot;">​</a></h4><p>冻结材料包 + <code>qoder-prompt.md</code> 统一提示。</p><h4 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h4><p>打开 QoderCN → 确认主窗口为 Quest → 新建/进入 Quest → 选择运行目录 → 保持默认模型与权限 → 粘贴统一提示发送。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h4><p>产品任务记录显示 08:13 开始、界面显示耗时 2 分钟；六份指定文件于 08:15:21 写入。</p><h4 id="验收情况" tabindex="-1">验收情况 <a class="header-anchor" href="#验收情况" aria-label="Permalink to &quot;验收情况&quot;">​</a></h4><ul><li>交付：6/6 一次生成，命名与位置合规；7/7 输入 SHA-256 与基线一致；</li><li>内容亮点：信息缺口分类清楚（新增项标注推断/建议）；结构可继续编辑；</li><li>内容偏差：读取了 input 之外的运行文件，把测试前状态写入成品（如「共同任务尚未执行」的过时结论）；自行生成七部分、12 章目录只能作为基准答卷；<strong>待办保持未勾选、自检却称 25 项全部通过</strong>——自检不可全信；</li><li>指标：澄清 0 / 权限确认 0 / 人工回复 0 / 中断 0 / 恢复 0。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>记录</th></tr></thead><tbody><tr><td>开始与完成时间</td><td>2026-08-12 08:13（任务记录）— 08:15:21（文件写入）</td></tr><tr><td>总用时</td><td>2 分钟（界面显示）</td></tr><tr><td>人工介入次数及原因</td><td>0</td></tr><tr><td>权限确认次数</td><td>0</td></tr><tr><td>生成或修改的交付文件</td><td>6/6 指定文件</td></tr><tr><td>是否一次通过验收</td><td>交付一次通过；权限边界与自检未通过完整验收</td></tr><tr><td>失败后的恢复路径</td><td>未触发</td></tr></tbody></table><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：现有代码项目的修改、审查与验证（代码优先型优势场景）。<strong>待 benchmark v2 统一测试</strong>。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p>候选：读取越界、权限不足、任务中断时的恢复。<strong>本轮未触发恢复场景</strong>；越界读取问题由产物证据证明，无需重新触发。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>读取范围越过 input</td><td>Quest/IDE 可索引整个工作空间</td><td>产物引用运行清单、验收表等，把测试前状态带入结果</td><td>验收中标注范围偏差；不把自检当作权限证据</td><td>新手可能不会意识到「未弹权限框」≠「只读指定目录」</td></tr><tr><td>自检不可全信</td><td>自检声称 25 项全通过，但漏掉越界读取、待办未勾选、.gitkeep</td><td>新手若只看自检会误判交付质量</td><td>以产物、文件系统与人工验收为准</td><td>需要教程示范独立核验</td></tr></tbody></table><p>本轮未出现执行错误或中断。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>追求速度与成本透明、以代码/Quest 任务为主的用户（2:00 / ¥0.25，人民币直显）；</li><li>需要审查提交能力（暂存/丢弃/提交）的代码用户；</li><li>中国区用户（人民币定价、国内模型渠道）。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>对数据边界敏感的读者（本轮存在无弹窗越权读取，教程明确标注）；</li><li>完全依赖 Agent 自检判断交付质量的用户（自检失真需人工核验）；</li><li>零基础新手（Quest 概念与 IDE 工作区需要适应）。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>有条件推荐</strong>——体验版免费可试；但首次使用就应检查产物是否引用了工作区其他文件；</li><li>什么条件下值得购买官方订阅：代码任务为主、速度与成本敏感时，专业版 ¥59/月起步性价比高；高级版按用量升级；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：<strong>代码/任务型主 Agent 候选</strong>（托管路径中效率最高）；</li><li>与相邻产品的差异：与 ZCode 同属代码优先型，Qoder 是托管 Auto 路径（快、便宜、但边界失分），ZCode 是 BYOK 路径（变更透明最强、需配置模型）；两者优势任务（代码）均待 v2 统一测试；</li><li>仍需要后续版本继续核验：越界读取是否修复、自检质量、代码优势任务、变更 diff 完整性。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>整体界面.png</td><td>Quest 任务卡与交付报告表</td><td>1.23.0</td><td>是</td><td>交付报告与操作统计</td></tr><tr><td>概览详情.png</td><td>预览/代码双视图</td><td>同上</td><td>是</td><td>概览页文档预览</td></tr><tr><td>审查详情.png</td><td>Git 暂存/丢弃/提交</td><td>同上</td><td>是</td><td>审查视图</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://qoder.cn/pricing" target="_blank" rel="noreferrer">Qoder CN Pricing</a>、<a href="https://docs.qoder.cn/product-overview/credits" target="_blank" rel="noreferrer">Qoder CN Credits</a>、<a href="https://docs.qoder.cn/user-guide/custom-model" target="_blank" rel="noreferrer">Qoder CN 自定义模型</a>、<a href="https://docs.qoder.cn/product-overview/qoderwork-cn-new-user-credits-claim-and-referral-reward-program-terms-and-conditions" target="_blank" rel="noreferrer">已截止的 QoderWork CN 活动规则</a>（访问日期 2026-08-11）</li><li>运行记录：<code>research/runs/2026-08-12-qoder-cn-v1.23.0/run-record.md</code></li><li>界面讲解：<code>docs/11-interface-guides/03-qoder-cn.md</code></li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（价格、Credits 规则）、实际测试（共同基准任务）、作者观察（界面与边界问题）、待验证（代码优势任务）。2 分钟、6.32 Credits、¥0.25 只对应本账号、本版本、本日期与 Auto 配置；不同产品 Credits 不是统一单位，不按数值横比。越界读取事实以产物证据为准，教程明确标注「效率与边界分开评价」。</p>',50)])])}const q=d(i,[["render",l]]);export{b as __pageData,q as default};
